package com.fasterxml.jackson.databind.node; import com.fasterxml.jackson.databind.*; import java.util.*; public class ArrayNode extends JsonNode { private final java.util.List<JsonNode> values=new ArrayList<>(); public ArrayNode add(JsonNode n){values.add(n);return this;} public ObjectNode addObject(){ObjectNode n=new ObjectNode();values.add(n);return n;} @Override public boolean isArray(){return true;} @Override public int size(){return values.size();} @Override public Iterator<JsonNode> iterator(){return values.iterator();} }